<script setup lang="ts">
import {userErrorMessage} from "./diagnostics.js"
import {computed,onMounted,onUnmounted,ref} from 'vue'
import {apiBases,authenticatedFetch,jsonResponse} from './http-client.js'
import {getVOSBearerToken,clearCachedVOSBearerToken} from './vos-auth'
const props=defineProps<{t:(text:string)=>string}>()
const base=apiBases(location.pathname).gateway
const auth={token:async()=>await getVOSBearerToken()||localStorage.getItem('v-router-key')||null,clearToken:clearCachedVOSBearerToken}
type Candidate={model:string;upstream_id:string;tier:string;tasks:string[];context_tokens:number;max_output_tokens:number;image_tokens:number|null;input_price:number|null;output_price:number|null;cold_start_ms:number}
type Config={enabled:boolean;policy:string;allow_cloud:boolean;candidates:Candidate[];classifier:string;jev_model:string;jev_upstream_id:string;allow_cloud_classifier:boolean;classifier_timeout_ms:number;request_type_tiers:Record<string,string>;context_simple_max_tokens:number;context_standard_max_tokens:number;revision:number}
const config=ref<Config|null>(null),catalog=ref<any[]>([]),saved=ref(''),error=ref(''),notice=ref(''),busy=ref(false),running=ref(false),search=ref('')
const decision=ref<any>(null),output=ref(''),stream=ref(false),localOnly=ref(false),session=ref(''),testPolicy=ref('balanced'),requestType=ref('')
const requestText=ref(JSON.stringify({model:'auto',messages:[{role:'user',content:'请总结这段文字：模型路由根据任务需求选择模型，本地计算仍需资源许可。'}],max_tokens:256},null,2))
let abort:AbortController|undefined
const dirty=computed(()=>!!config.value&&JSON.stringify(config.value)!==saved.value)
const rows=computed(()=>catalog.value.filter(m=>m.endpoints?.includes('chat_completions')&&!m.virtual&&`${m.qualified} ${m.upstream_name}`.toLowerCase().includes(search.value.toLowerCase())))
const modelClassifier=computed(()=>['jev','systemone','llm'].includes(config.value?.classifier||''))
const classifiers=computed(()=>catalog.value.filter(m=>!m.virtual&&m.endpoints?.includes(config.value?.classifier==='llm'?'chat_completions':'systemone')))
const taskTypes=['general','code','translation','summary','reasoning']
const taskNames:Record<string,string>={general:'通用对话',code:'编程',translation:'翻译',summary:'总结',reasoning:'推理'}
const classifierKey=computed({get:()=>JSON.stringify([config.value?.jev_model||'',config.value?.jev_upstream_id||'']),set:(value:string)=>{if(config.value){[config.value.jev_model,config.value.jev_upstream_id]=JSON.parse(value)}}})
const policies=[['balanced','均衡'],['fast','速度'],['quality','质量'],['economy','省成本']]
async function api(path:string,body?:unknown,method?:string){return jsonResponse(await authenticatedFetch(base+path,{method:method||(body===undefined?'GET':'POST'),headers:body===undefined?undefined:{'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body)},auth))}
async function load(){busy.value=true;error.value='';try{const [value,models]=await Promise.all([api('/api/v1/auto-routing'),api('/api/v1/auto-routing/candidates')]);config.value=value;catalog.value=models.models;saved.value=JSON.stringify(value);testPolicy.value=value.policy;decision.value=null;notice.value=''}catch(e){error.value=userErrorMessage(e)}finally{busy.value=false}}
function selected(m:any){return config.value?.candidates.some(c=>c.model===m.qualified&&c.upstream_id===m.upstream_id)}
function toggle(m:any){if(!config.value)return;const index=config.value.candidates.findIndex(c=>c.model===m.qualified&&c.upstream_id===m.upstream_id);if(index>=0)config.value.candidates.splice(index,1);else config.value.candidates.push({model:m.qualified,upstream_id:m.upstream_id,tier:'standard',tasks:[],context_tokens:32768,max_output_tokens:4096,image_tokens:null,input_price:null,output_price:null,cold_start_ms:10000})}
function task(c:Candidate,event:Event){c.tasks=(event.target as HTMLInputElement).value.split(',').map(s=>s.trim()).filter(Boolean)}
async function save(){if(!config.value)return;busy.value=true;error.value='';notice.value='';try{const value=JSON.parse(JSON.stringify(config.value));for(const c of value.candidates)for(const key of ['input_price','output_price','image_tokens'])if(c[key]==='')c[key]=null;config.value=await api('/api/v1/auto-routing',value,'PUT');saved.value=JSON.stringify(config.value);notice.value=props.t('配置已保存');decision.value=null}catch(e){error.value=userErrorMessage(e)}finally{busy.value=false}}
async function run(actual=false){running.value=true;error.value='';output.value='';abort=new AbortController();try{const body=JSON.parse(requestText.value);body.model='auto';body.stream=actual&&stream.value;const headers:Record<string,string>={'Content-Type':'application/json','X-VScheduler-Auto-Policy':testPolicy.value,'X-VScheduler-Auto-Local-Only':String(localOnly.value),'X-VScheduler-Queue-Wait-Seconds':'120'};if(session.value)headers['X-VScheduler-Session-ID']=session.value;if(config.value?.classifier==='request_type'&&requestType.value)headers['X-VScheduler-Auto-Task']=requestType.value;const response=await authenticatedFetch(base+(actual?'/v1/chat/completions':'/api/v1/auto-routing/test'),{method:'POST',headers,body:JSON.stringify(body),signal:abort.signal},auth);if(!response.ok)await jsonResponse(response);if(!actual){decision.value=await jsonResponse(response);return}output.value=`${props.t('实际模型')}: ${response.headers.get('x-vscheduler-auto-model')||'—'}\n`;if(body.stream){const reader=response.body!.getReader(),decoder=new TextDecoder();while(true){const {value,done}=await reader.read();if(done)break;output.value+=decoder.decode(value,{stream:true})}output.value+=decoder.decode()}else output.value+=JSON.stringify(await jsonResponse(response),null,2)}catch(e){error.value=userErrorMessage(e)}finally{running.value=false;abort=undefined}}
onMounted(load)
onUnmounted(()=>abort?.abort())
</script>
<template>
 <div class="auto-routing">
  <div v-if="error" role="alert" class="error">{{error}}</div><p v-if="notice" role="status">{{notice}}</p>
  <section class="panel auto-section">
   <div class="section-head"><div><h2>{{t('Auto 自动选型')}}</h2><p>{{t('勾选候选模型，按任务和资源状态选择；本地调用继续经过资源准入。')}}</p></div><button class="quiet" :disabled="busy||running||dirty" @click="load">{{t('刷新')}}</button></div>
   <p v-if="!config">{{t('Auto 配置需要管理员身份。')}}</p>
   <template v-if="config">
    <div class="auto-settings"><label class="check"><input type="checkbox" v-model="config.enabled">{{t('启用 Auto')}}</label><label>{{t('默认策略')}}<select v-model="config.policy" :aria-label="t('默认策略')"><option v-for="p in policies" :key="p[0]" :value="p[0]">{{t(p[1]!)}}</option></select></label><label class="check"><input type="checkbox" v-model="config.allow_cloud">{{t('允许云端回答')}}</label><label>{{t('路由方式')}}<select v-model="config.classifier" :aria-label="t('路由方式')"><option value="rules">{{t('本地规则')}}</option><option value="request_type">{{t('按请求类型')}}</option><option value="context_size">{{t('按上下文大小')}}</option><option value="llm">{{t('聊天模型分类器（本地／云端）')}}</option><option value="jev">{{t('Jev 可选分类器')}}</option><option value="systemone">{{t('System One 本地／云端分类器')}}</option></select></label></div>
    <p>{{t('规则无需额外模型。复杂任务只选 complex 档位；默认候选为 standard，请按实际能力设置。')}}</p>
    <div v-if="modelClassifier" class="auto-settings"><label class="check"><input type="checkbox" v-model="config.allow_cloud_classifier">{{t('允许云端分类')}}</label><label>{{t('分类模型')}}<select v-model="classifierKey" :aria-label="t('分类模型')"><option :value="JSON.stringify(['',''])">{{t('请选择')}}</option><option v-for="m in classifiers" :key="m.upstream_id+m.qualified" :value="JSON.stringify([m.qualified,m.upstream_id])">{{m.qualified}} · {{m.upstream_name}}</option></select></label><label>{{t('分类超时（毫秒）')}}<input type="number" min="100" max="120000" v-model.number="config.classifier_timeout_ms"></label><p>{{t('分类失败回退规则。仅本地请求可调用本地决策模型，不调用云端分类器。')}}</p></div>
    <div v-if="config.classifier==='request_type'" class="auto-settings"><label v-for="task in taskTypes" :key="task">{{t(taskNames[task]!)}}<select v-model="config.request_type_tiers[task]" :aria-label="task+' tier'"><option value="simple">simple</option><option value="standard">standard</option><option value="complex">complex</option></select></label><p>{{t('通过 X-VScheduler-Auto-Task 指定请求类型；未指定时按文本规则识别，无需分类模型。')}}</p></div>
    <div v-if="config.classifier==='context_size'" class="auto-settings"><label>{{t('simple 上下文上限')}}<input type="number" min="512" v-model.number="config.context_simple_max_tokens" :aria-label="t('simple 上下文上限')"></label><label>{{t('standard 上下文上限')}}<input type="number" min="513" v-model.number="config.context_standard_max_tokens" :aria-label="t('standard 上下文上限')"></label><p>{{t('按完整输入与输出上限的保守 token 预算分档；图片计入候选最大声明预算。长度不代表任务难度。')}}</p></div>
    <label>{{t('搜索候选模型')}}<input v-model="search" type="search" :placeholder="t('模型或上游名称')"></label>
    <div class="candidate-list"><label class="candidate check" v-for="m in rows" :key="m.upstream_id+m.qualified"><input type="checkbox" :checked="selected(m)" @change="toggle(m)"><span><strong>{{m.qualified}}</strong><small>{{m.upstream_name}} · {{m.upstream_id}} · {{m.capabilities?.join(', ')}}</small></span></label><p v-if="!rows.length">{{t('没有可选聊天模型，请先添加或注册上游。')}}</p></div>
    <h3>{{t('已选候选与能力档位')}}</h3><p>{{t('上下文和能力须与实际服务配置一致；价格单位为美元/百万 token，留空表示未知。图片 token 预算留空时不承接图片请求。')}}</p>
    <div v-for="c in config.candidates" :key="c.upstream_id+c.model" class="candidate-profile"><div class="profile-title"><strong>{{c.model}}</strong><code>{{c.upstream_id}}</code><button class="quiet" @click="config.candidates=config.candidates.filter(v=>v!==c)">{{t('移除')}}</button></div><div class="profile-fields"><label>{{t('能力档位')}}<select v-model="c.tier"><option value="simple">simple</option><option value="standard">standard</option><option value="complex">complex</option></select></label><label>{{t('上下文 token')}}<input type="number" min="512" v-model.number="c.context_tokens"></label><label>{{t('最大输出 token')}}<input type="number" min="1" v-model.number="c.max_output_tokens"></label><label>{{t('每张图片 token 预算')}}<input type="number" min="1" v-model.number="c.image_tokens"></label><label>{{t('输入价格')}}<input type="number" min="0" step="any" v-model.number="c.input_price"></label><label>{{t('输出价格')}}<input type="number" min="0" step="any" v-model.number="c.output_price"></label><label>{{t('冷启动估计（毫秒）')}}<input type="number" min="0" v-model.number="c.cold_start_ms"></label><label>{{t('任务类型（逗号分隔，空为全部）')}}<input :value="c.tasks.join(',')" @change="task(c,$event)" placeholder="general,code,translation,summary,reasoning"></label></div></div>
    <p v-if="!config.candidates.length">{{t('尚未选择候选模型。')}}</p><div class="auto-actions"><button :disabled="busy||running||!dirty" @click="save">{{t('保存配置')}}</button><span v-if="dirty">{{t('保存配置后测试与调用。')}}</span><code>revision {{config.revision}}</code></div>
   </template>
  </section>
  <section v-if="config" class="panel auto-section"><h2>{{t('测试选型与实际调用')}}</h2><p>{{t('规则、请求类型和上下文策略不运行分类模型。模型分类可能消耗本地算力或云端费用，实际调用另运行回答模型。')}}</p><div class="auto-settings"><label>{{t('本次策略')}}<select v-model="testPolicy" :aria-label="t('本次策略')"><option v-for="p in policies" :key="p[0]" :value="p[0]">{{t(p[1]!)}}</option></select></label><label v-if="config.classifier==='request_type'">{{t('本次请求类型')}}<select v-model="requestType" :aria-label="t('本次请求类型')"><option value="">{{t('自动识别')}}</option><option v-for="task in taskTypes" :key="task" :value="task">{{t(taskNames[task]!)}}</option></select></label><label class="check"><input type="checkbox" v-model="localOnly">{{t('仅本地')}}</label><label class="check"><input type="checkbox" v-model="stream">{{t('流式响应')}}</label><label>{{t('会话 ID（可选）')}}<input v-model="session" maxlength="96"></label></div><label>Chat Completions JSON<textarea v-model="requestText" rows="9" spellcheck="false" aria-label="Chat Completions JSON"></textarea></label><div class="auto-actions"><button :disabled="running||busy||dirty||!config.enabled" @click="run()">{{t('测试选型')}}</button><button class="quiet" :disabled="running||busy||dirty||!config.enabled" @click="run(true)">{{t('实际调用')}}</button><button v-if="running" class="quiet" @click="abort?.abort()">{{t('取消')}}</button></div>
   <div v-if="decision" class="routing-result" aria-live="polite"><h3>{{t('选型结果')}}</h3><p><strong>{{decision.resolved_model||t('无合格候选')}}</strong> · {{decision.upstream_id}} · {{decision.reason}}</p><p>{{decision.classification.task}} / {{decision.classification.complexity}} · {{decision.classification.source}} · {{decision.classification.elapsed_ms}} ms <span v-if="decision.classification.fallback">· {{t('已回退规则')}}</span></p><div class="table-wrap"><table><thead><tr><th>{{t('模型')}}</th><th>{{t('上游')}}</th><th>{{t('是否合格')}}</th><th>{{t('原因')}}</th></tr></thead><tbody><tr v-for="c in decision.candidates" :key="c.upstream_id+c.model"><td>{{c.model}}</td><td>{{c.upstream_id}}</td><td>{{t(c.eligible?'是':'否')}}</td><td>{{c.reason}}</td></tr></tbody></table></div></div><pre v-if="output" class="actual-output" aria-live="polite">{{output}}</pre>
  </section>
 </div>
</template>
<style scoped>
.auto-routing{display:grid;grid-template-columns:minmax(0,1fr);min-width:0;gap:20px}.auto-section{padding:24px;min-width:0}.auto-section h2{margin:0 0 12px}.auto-section p{color:#64748b;line-height:1.6}.auto-settings,.profile-fields{display:flex;flex-wrap:wrap;gap:16px;margin:18px 0}.auto-routing label{display:flex;flex-direction:column;gap:7px;font-size:13px}.auto-routing .check{flex-direction:row;align-items:center}.check input{width:16px;height:16px;flex:none}.auto-routing input,.auto-routing select,.auto-routing textarea{max-width:100%;box-sizing:border-box}.profile-fields label{flex:1 1 170px;min-width:0}.profile-fields input{width:100%}.candidate-list{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,300px),1fr));gap:10px;max-height:340px;overflow:auto;margin:16px 0}.candidate{padding:12px;border:1px solid #e2e8f0;border-radius:10px;overflow-wrap:anywhere}.candidate small{display:block;margin-top:5px;color:#64748b}.candidate-profile{border-top:1px solid #e2e8f0;padding:16px 0}.profile-title,.auto-actions{display:flex;align-items:center;gap:12px;flex-wrap:wrap}.profile-title strong{overflow-wrap:anywhere}.profile-title button{margin-left:auto}.profile-title code{font-size:11px}.auto-actions{margin-top:16px}.auto-actions span{color:#64748b;font-size:13px}.auto-routing textarea,.actual-output{width:100%;font-family:ui-monospace,monospace;font-size:13px}.actual-output{box-sizing:border-box;padding:16px;background:#f1f5f9;white-space:pre-wrap;overflow-wrap:anywhere;max-height:600px;overflow:auto}.routing-result{margin-top:24px;min-width:0}.auto-routing .table-wrap{max-width:100%;overflow-x:auto}.routing-result p{overflow-wrap:anywhere}.auto-section .section-head{align-items:flex-start}@media(max-width:600px){.auto-section{padding:16px}.auto-settings>label{width:100%}.profile-title code{width:100%;overflow-wrap:anywhere}}
</style>
